package com.lianxibu.site.service.learning;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;
import com.lianxibu.site.service.jobs.SharedWriteExecutor;
import com.lianxibu.site.service.jobs.SharedWriteExecutor.ActionContext;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import com.lianxibu.site.service.learning.PackageLifecycleService.*;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionSynchronizationManager;
class PackageLifecycleServiceTest {
 JdbcTemplate jdbc;PackageLifecycleService service;Fixture store;final Actor owner=new Actor("fictional-owner","owner");
 @BeforeEach void setup(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:fictional-package-"+System.nanoTime()+";DB_CLOSE_DELAY=-1");jdbc=new JdbcTemplate(ds);jdbc.execute("CREATE TABLE worker_lock(id INT PRIMARY KEY)");jdbc.update("INSERT INTO worker_lock VALUES(1)");jdbc.execute("CREATE TABLE packages(id VARCHAR(64) PRIMARY KEY,state VARCHAR(16),revision BIGINT)");jdbc.execute("CREATE TABLE receipts(action_key VARCHAR(128) PRIMARY KEY,command_hash VARCHAR(64),package_id VARCHAR(64),revision BIGINT,state VARCHAR(16))");jdbc.update("INSERT INTO packages VALUES('fictional-package','draft',0),('fictional-other','published',9)");store=new Fixture();service=new PackageLifecycleService(new SharedWriteExecutor(new JdbcSharedWriteEntry(ds),new DataSourceTransactionManager(ds)),store);}
 ActionContext context(String key){return new ActionContext(key,"fictional-reserved",null);}
 Result run(long expected,Action requested,String key){return service.action(owner,"fictional-package",expected,requested,"Fictional reason",context(key));}
 String state(){return jdbc.queryForObject("SELECT state FROM packages WHERE id='fictional-package'",String.class);}
 long revision(){return jdbc.queryForObject("SELECT revision FROM packages WHERE id='fictional-package'",Long.class);}
 int receipts(){return jdbc.queryForObject("SELECT COUNT(*) FROM receipts",Integer.class);}
 @Test void fourActionsStartAtKnownZeroAndOnlyChangePackage(){assertEquals(1,run(0,Action.APPROVE,"fictional-approve").revision());assertEquals("approved",state());run(1,Action.PUBLISH,"fictional-publish");assertEquals("published",state());run(2,Action.WITHDRAW,"fictional-withdraw");assertEquals("withdrawn",state());run(3,Action.APPROVE,"fictional-reapprove");run(4,Action.REJECT,"fictional-reject");assertEquals("draft",state());assertEquals(5,revision());assertEquals(5,receipts());assertEquals(3,store.validations);assertEquals(9,jdbc.queryForObject("SELECT revision FROM packages WHERE id='fictional-other'",Long.class));}
 @Test void staleRevisionAndInvalidStateNeverCommit(){var failure=assertThrows(Rejected.class,()->run(1,Action.APPROVE,"fictional-stale"));assertEquals("revision_conflict",failure.getMessage());assertThrows(Rejected.class,()->run(0,Action.PUBLISH,"fictional-premature"));assertThrows(Rejected.class,()->run(0,Action.WITHDRAW,"fictional-withdraw-draft"));assertEquals(0,receipts());assertEquals(0,revision());}
 @Test void approveAndPublishNeedSameLockedPackageRevisionProof(){for(int mode:new int[]{1,2,3,4}){store.proofMode=mode;RuntimeException failure=assertThrows(RuntimeException.class,()->run(0,Action.APPROVE,"fictional-proof-"+mode));assertTrue(mode==4?failure instanceof Rejected:failure instanceof Unavailable);assertEquals(0,revision());assertEquals(0,receipts());}store.proofMode=0;run(0,Action.APPROVE,"fictional-valid");store.proofMode=4;assertThrows(Rejected.class,()->run(1,Action.PUBLISH,"fictional-invalid-publish"));assertEquals("approved",state());run(1,Action.WITHDRAW,"fictional-withdraw-without-validation");assertEquals("withdrawn",state());}
 @Test void sameKeyCommandReplayAndEntryLockRecheckHaveOneEffect(){Result first=run(0,Action.APPROVE,"fictional-stable");Result replay=run(0,Action.APPROVE,"fictional-stable");assertTrue(replay.replayed());assertEquals(first.revision(),replay.revision());store.hideOnce=true;assertTrue(run(0,Action.APPROVE,"fictional-stable").replayed());assertEquals(1,store.transitions);assertEquals(1,receipts());assertEquals(1,revision());assertThrows(Rejected.class,()->service.action(owner,"fictional-package",0,Action.APPROVE,"Fictional different reason",context("fictional-stable")));assertThrows(Rejected.class,()->service.action(new Actor("fictional-other-owner","owner"),"fictional-package",0,Action.APPROVE,"Fictional reason",context("fictional-stable")));}
 @Test void unauthorizedAndMalformedUnicodeOrUnsafeIncrementNeverReadReceipts(){for(Actor actor:new Actor[]{null,new Actor("fictional-user","user")})assertThrows(Denied.class,()->service.action(actor,"fictional-package",0,Action.APPROVE,"Fictional",context("fictional-denied")));for(String id:new String[]{"bad\n","\ud800","x".repeat(65)})assertThrows(IllegalArgumentException.class,()->service.action(owner,id,0,Action.APPROVE,"Fictional",context("fictional-invalid")));for(String reason:new String[]{""," ","🙂".repeat(2049),"\ud800"})assertThrows(IllegalArgumentException.class,()->service.action(owner,"fictional-package",0,Action.APPROVE,reason,context("fictional-invalid")));for(long revision:new long[]{-1,9007199254740991L})assertThrows(IllegalArgumentException.class,()->run(revision,Action.APPROVE,"fictional-invalid"));assertThrows(IllegalArgumentException.class,()->service.action(owner,"fictional-package",0,Action.APPROVE,"Fictional",context("bad\n")));assertEquals(0,store.lookups);}
 @Test void receiptFailureAfterStateWriteRollsBackAndSameOriginalCanRecover(){store.receiptFailure=true;assertThrows(IllegalStateException.class,()->run(0,Action.APPROVE,"fictional-failed-receipt"));assertEquals(0,revision());assertEquals("draft",state());assertEquals(0,receipts());store.receiptFailure=false;assertFalse(run(0,Action.APPROVE,"fictional-failed-receipt").replayed());assertEquals(1,revision());}
 @Test void missingOrWrongWriteReceiptRollsBackPackage(){store.dropReceipt=true;assertThrows(Unavailable.class,()->run(0,Action.APPROVE,"fictional-missing-receipt"));assertEquals(0,revision());store.dropReceipt=false;store.wrongReceipt=true;assertThrows(Unavailable.class,()->run(0,Action.APPROVE,"fictional-wrong-receipt"));assertEquals(0,revision());assertEquals(0,receipts());}
 @Test void unknownRevisionStateOrWrongLockedTargetIsNotCASProof(){jdbc.update("UPDATE packages SET revision=NULL WHERE id='fictional-package'");assertThrows(Unavailable.class,()->run(0,Action.APPROVE,"fictional-unknown"));jdbc.update("UPDATE packages SET revision=0,state=NULL WHERE id='fictional-package'");assertThrows(Unavailable.class,()->run(0,Action.APPROVE,"fictional-state"));jdbc.update("UPDATE packages SET state='draft' WHERE id='fictional-package'");store.wrongRow=true;assertThrows(Unavailable.class,()->run(0,Action.APPROVE,"fictional-wrong-row"));assertEquals(0,receipts());}
 @Test void codePointReasonBoundaryAndOriginalBytesArePreserved(){String reason="🙂".repeat(2048);service.action(owner,"fictional-package",0,Action.APPROVE,reason,context("fictional-unicode"));assertEquals(reason,store.lastReason);}
 final class Fixture implements Store {
  int validations,transitions,lookups,proofMode;boolean hideOnce,receiptFailure,dropReceipt,wrongReceipt,wrongRow;String lastReason;
  public Result committed(String key,String hash){lookups++;if(hideOnce){hideOnce=false;return null;}var rows=jdbc.queryForList("SELECT * FROM receipts WHERE action_key=?",key);if(rows.isEmpty())return null;var r=rows.getFirst();if(!hash.equals(r.get("COMMAND_HASH")))throw new Rejected("identity_conflict");return new Result((String)r.get("PACKAGE_ID"),((Number)r.get("REVISION")).longValue(),(String)r.get("STATE"),false);}
  public Current locked(String id){assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var rows=jdbc.queryForList("SELECT * FROM packages WHERE id=? FOR UPDATE",id);if(rows.isEmpty())return null;var r=rows.getFirst();return new Current(wrongRow?"fictional-other":id,(Long)r.get("REVISION"),(String)r.get("STATE"));}
  public Validation validateLocked(Current row){assertTrue(TransactionSynchronizationManager.isActualTransactionActive());validations++;return proofMode==1?null:new Validation(proofMode==2?"fictional-other":row.packageId(),proofMode==3?row.revision()+1:row.revision(),proofMode!=4);}
  public void transition(Current row,String target,String reason,String hash,ActionContext context){assertTrue(TransactionSynchronizationManager.isActualTransactionActive());transitions++;lastReason=reason;jdbc.update("UPDATE packages SET state=?,revision=revision+1 WHERE id=? AND revision=?",target,row.packageId(),row.revision());if(receiptFailure)throw new IllegalStateException("Fictional receipt failure");if(!dropReceipt)jdbc.update("INSERT INTO receipts VALUES(?,?,?,?,?)",context.actionKey(),hash,wrongReceipt?"fictional-other":row.packageId(),row.revision()+1,target);}
 }
}
